window.docContents[127].resolve({"/Lecture-1___-Motivation-and-Propositional-Logic/Worked-Examples/#Formal-Software-Verification--Lecture-1___-Motivation-and-Propositional-Logic--Worked-Examples":{"contents":"Each example below appears three ways, as a natural deduction derivation, as a proof term, and as a tactic proof. The three present the same proof, and Lean checks both proof scripts when the notes are built. These propositions are disjoint from the examples of the earlier sections and from the exercises.\n\n\n\n\n\n\n\n\n\n\n\n","context":"Formal Software Verification\u0009Lecture 1: Motivation and Propositional Logic","header":"1.8. Worked Examples","id":"/Lecture-1___-Motivation-and-Propositional-Logic/Worked-Examples/#Formal-Software-Verification--Lecture-1___-Motivation-and-Propositional-Logic--Worked-Examples"}});